{
  "case_id": "xsu_sg_011_doctor_certificate",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Kernepunkterne er korrekte: lægeattest kan indhentes, den skal belyse funktionsevnen, og lægen skal redegøre for behandling eller henvisning. Svaret tilføjer dog, at Udbetaling Danmark kan afvise ansøgningen uden realitetsbehandling, hvis minimumskravene ikke er opfyldt. Det fremgår ikke af de leverede kilder. Svaret hævder også, at kun 'særlige tilfælde' giver adgang til supplerende lægefaglige oplysninger, og det blander attestindhentning sammen med journaloplysninger og sagkyndig udtalelse. Det er væsentlige juridiske unøjagtigheder."
    },
    "c02_required_elements_complete": {
      "label": "met",
      "reason": "Alle tre kritiske elementer er med: attest kan indhentes ved utilstrækkelig dokumentation, attesten belyser funktionsevnen i forhold til den søgte funktionsnedsættelse, og den belyser behov for fortsat behandling eller henvisning til specialist. Svaret nævner ikke udtrykkeligt, at det er den praktiserende læge, men det gør det nærmest implicit."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret behandler begge dele af spørgsmålet: hvad Udbetaling Danmark kan gøre, og hvad attesten skal beskrive."
    },
    "c04_source_traceability": {
      "label": "met",
      "reason": "Svaret henviser til en identificerbar kilde, Vejledning nr. 10157 af 5. oktober 2026, og bruger nummererede henvisninger. Nogle påstande er ikke direkte knyttet til en kilde."
    },
    "c05_source_validity": {
      "label": "met",
      "reason": "Vejledning nr. 10157 findes i det frosne materiale, er aktuel og er autoritativ og anvendelig til spørgsmålet. Afsnit 5.1.2 dækker lægeattesten."
    },
    "c06_claim_source_support": {
      "label": "not_met",
      "reason": "Den citerede passage understøtter, at attest kan indhentes, og hvad den skal beskrive. Påstanden om afvisning uden realitetsbehandling ved manglende minimumsdokumentation (henvisning 3 og 2) understøttes ikke af afsnit 5.1.2. Henvisning 3 refererer til en kilde, der ikke er vist. Påstanden om, at supplerende lægefaglige oplysninger kun kan indhentes 'i særlige tilfælde', er kun delvist dækket af kilden."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer en retsvirkning, nemlig afvisning uden realitetsbehandling, som ikke fremgår af de leverede kilder. Bekendtgørelsens § 37, stk. 5 om frist for yderligere dokumentation nævnes ikke. Udsagnet om, at Udbetaling Danmark 'først forsøger at få sagen belyst', er en uunderbygget praksisantagelse."
    },
    "c08_qualifications_and_exceptions": {
      "label": "met",
      "reason": "'Kan' bevares som mulighed og ikke pligt. Fremmøde er ikke omtalt, så forbeholdet kræves ikke. 'Særlige tilfælde' er bevaret for de supplerende oplysninger, men er sat i forkert sammenhæng."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Fremstillingen er intern sammenhængende: utilstrækkelig dokumentation giver mulighed for attest, og attesten skal beskrive funktionsevne og behandlingsbehov. Den tilføjede afvisningsbemærkning er uunderbygget, men modsiger ikke de øvrige trin."
    },
    "c10_legal_modality_precision": {
      "label": "met",
      "reason": "Svaret gengiver 'kan' for indhentning og 'skal' for attestens indhold korrekt. 'Typisk' om afvisning er blødt formuleret, men det gælder en uunderbygget påstand, som er vurderet under C07."
    }
  },
  "xhaile_coverage": {
    "A61": {
      "label": "partial",
      "reason": "Svaret dækker, at attest kan indhentes, og hvad den skal indeholde. Det udelader kravet om fremmøde, betaling af udgifter og journaloplysninger. Journaloplysninger er blandet sammen med 'supplerende lægefaglige oplysninger' og fremstillet upræcist."
    }
  },
  "overall_notes": "Kerneindholdet om lægeattesten er korrekt og fuldstændigt. Svaret er dog svækket af en uunderbygget påstand om afvisning uden realitetsbehandling, citeret til kilder der ikke understøtter den. Det kan ikke vurderes som fuldt juridisk korrekt eller fuldt kildestøttet."
}

